顺序表的按位查找
GetElem(L,i)：按位查找操作。获取表L中第i个位置的元素的值。
#define MaxSize 10
//定义最大长度
typedef struct{
ElemType data[MaxSize];
//用静态的“数组”存放数据元素
int length;
//顺序表的当前长度
}SqList;
//顺序表的类型定义（静态分配方式）
静态分配
ElemType GetElem(SqList L, int i){
return L.data[i-1];
}

